sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
console.log('teeeeeeee')
    var jsobpub = "";
    var publishersList = api.data.gettoppublisheronly_1.output.grouped_publishers;
    for (var i = 0; i < publishersList.length; i++) {
        if (jsobpub == "") {
            console.log('oooooooooooooooooooo')
            jsobpub = '"'+ publishersList[i] + '":{ "label":"' + publishersList[i] +'"}';
        } else {
            jsobpub = jsobpub + "," + '"'+ publishersList[i] + '":{ "label":"' + publishersList[i] +'"}';
        }
    };

    var finalstr = '{"' +"publisher"+ '":{' + jsobpub + '}}';
    var jsk = JSON.parse(finalstr);
    console.log("OldData",jsk)
    return jsk;
}
